/// One stroke as a smooth path (Catmull-Rom through its points), scaled into
/// the rect's largest centred square. Trimmed to draw and to rub out.
struct LogoStrokeShape: Shape {
    let stroke: LogoStrokes.Stroke

    func path(in rect: CGRect) -> Path {
        let side = min(rect.width, rect.height)
        let mid = CGPoint(x: rect.midX, y: rect.midY)
        let pts = stroke.points.map { CGPoint(x: mid.x + $0.x * side, y: mid.y + $0.y * side) }
        var path = Path()
        guard pts.count > 1 else { return path }
        if pts.count == 2 {
            path.move(to: pts[0]); path.addLine(to: pts[1]); return path
        }
        let n = pts.count
        func at(_ i: Int) -> CGPoint {
            stroke.closed ? pts[(i % n + n) % n] : pts[min(max(i, 0), n - 1)]
        }
        path.move(to: pts[0])
        let segments = stroke.closed ? n : n - 1
        for i in 0..<segments {
            let p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2)
            let c1 = CGPoint(x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6)
            let c2 = CGPoint(x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6)
            path.addCurve(to: p2, control1: c1, control2: c2)
        }
        if stroke.closed { path.closeSubpath() }
        return path
    }
}
